take values: move [Int; ~] -> Int {
    values -> len
}
main {
    [1, 2; ~] => values
    values -> take => count
}

outer: -> Int {
    inner: -> Int {
        [1, 2] => values
        values[0]
    }
    [3; 3] => outerValues
    inner() + outerValues[0]
}
main {
    outer() => result
}

combine left: Int, right: Int -> Int => left + right
main {
    1 -> combine(true -> if {
        2 => first
        first
    } else {
        3 => second
        second
    }) => answer
}

main {
    2 -> when {
        == 1 => 10
        else => 20
    } => answer
}

main {
    1..3 -> fold 0 total, item {
        total + item => next
        next
    } => answer
}

main {
    "value=$(true -> if { 2 } else { 3 })" -> println
}

# Result-producing block functions compose as ordinary pipeline stages.
map value: Int -> Int block item: Int -> Int {
    value -> yield
}

filter value: Int -> Int block item: Int -> Bool {
    value -> yield => accepted
    accepted -> if { value } else { 0 }
}

tap value: Int -> Int block item: Int {
    value -> yield
    value
}

main {
    5
        -> map { it * 3 }
        -> tap { "tap=$it" -> println }
        -> filter { it > 10 }
        => result

    "result=$result" -> println
}

main {
    0 => counter!
    counter! < 1 -> while {
        counter! + 1 => counter!
    }
    counter! => answer
}

main {
    2 -> when {
        == 1 {
            10 => one
            one
        }
        else {
            20 => other
            other
        }
    } => answer
}

plus value: Int, delta: Int -> Int => value + delta
map value: Int -> Int block item: Int -> Int {
    value -> yield
}
main {
    5
        -> plus(true -> if {
            2 => increment
            increment
        } else { 3 })
        -> map { it * 2 }
        => result
}

